class StandardDomain(Domain):
    """
    Standard domain.
    """

    name = 'std'
    label = 'Standard'

    object_types = {
        'program': ObjType(_('program'), 'exec', 'program'),
        'cmdoption': ObjType(_('program option'), 'option'),
        'option': ObjType(_('program option'), 'option'),
        'envvar': ObjType(_('environment variable'), 'envvar'),
        'token': ObjType(_('grammar token'), 'token'),
        'term': ObjType(_('glossary term'), 'term', 'search'),
        'label': ObjType(_('reference label'), 'ref', 'keyword'),
    }

    dangling_warnings = {
        'program': _('Undocumented C++ declaration: %(target)s'),
        'cmdoption': _('Undocumented C++ declaration: %(target)s'),
        'option': _('Undocumented C++ declaration: %(target)s'),
        'envvar': _('Undocumented C++ declaration: %(target)s'),
        'token': _('Undocumented C++ declaration: %(target)s'),
        'term': _('Undocumented C++ declaration: %(target)s'),
        'label': _('Undocumented C++ declaration: %(target)s'),
    }

    initial_data = {
        'progoptions': {},      # (program, name) -> docname, labelid
        'objects': {},          # (type, name) -> docname, labelid
        'labels': {},           # name -> docname, labelid, sectionname
        'anonlabels': {},       # name -> docname, labelid
    }

    def __init__(self, env: "BuildEnvironment") -> None:
        super().__init__(env)

        self.progoptions = {}   # (program, name) -> docname, labelid
        self.objects = {}       # (type, name) -> docname, labelid
        self.labels = {}        # name -> docname, labelid, sectionname
        self.anonlabels = {}    # name -> docname, labelid

    def clear_doc(self, docname: str) -> None:
        for (prog, option), (doc, _labelid) in list(self.progoptions.items()):
            if doc == docname:
                del self.progoptions[prog, option]

        for (typ, name), (doc, _labelid) in list(self.objects.items()):
            if doc == docname:
                del self.objects[typ, name]

        for name, (doc, _labelid, _sectionname) in list(self.labels.items()):
            if doc == docname:
                del self.labels[name]

        for name, (doc, _labelid) in list(self.anonlabels.items()):
            if doc == docname:
                del self.anonlabels[name]

    def merge_domaindata(self, docnames: List[str], otherdata: Dict) -> None:
        for (prog, option), (doc, labelid) in otherdata['progoptions'].items():
            if doc in docnames:
                self.progoptions[prog, option] = doc, labelid

        for (typ, name), (doc, labelid) in otherdata['objects'].items():
            if doc in docnames:
                self.objects[typ, name] = doc, labelid

        for name, (doc, labelid, sectionname) in otherdata['labels'].items():
            if doc in docnames:
                self.labels[name] = doc, labelid, sectionname

        for name, (doc, labelid) in otherdata['anonlabels'].items():
            if doc in docnames:
                self.anonlabels[name] = doc, labelid

    def process_doc(self, env: "BuildEnvironment", docname: str, document: nodes.document) -> None:
        for name, explicit in document.nametypes.items():
            if explicit:
                if name in self.labels:
                    logger.warning(__('duplicate label %s, other instance in %s'),
                                   name, self.env.doc2path(self.labels[name][0]),
                                   location=document)
                self.anonlabels[name] = docname, name
                self.labels[name] = docname, name, ''
            else:
                self.anonlabels[name] = docname, name

    def note_object(self, objtype: str, name: str, labelid: str, location: Node = None) -> None:
        """Note a generic object for cross reference.

        .. versionadded:: 2.1
        """
        if (objtype, name) in self.objects:
            docname, labelid = self.objects[objtype, name]
            logger.warning(__('duplicate %s description of %s, other instance in %s'),
                           objtype, name, docname, location=location)
        self.objects[objtype, name] = self.env.docname, labelid

    def note_program_option(self, program: str, name: str, docname: str, labelid: str) -> None:
        if (program, name) in self.progoptions:
            logger.warning(__('duplicate option description of %s, other instance in %s'),
                           name, self.env.doc2path(self.progoptions[program, name][0]))
        self.progoptions[program, name] = docname, labelid

    def add_program_option(self, program: str, name: str, docname: str, labelid: str) -> None:
        warnings.warn('StandardDomain.add_program_option() is deprecated.',
                      RemovedInSphinx40Warning, stacklevel=2)
        self.note_program_option

